ALTER TABLE public.transactions ADD COLUMN payment_method TEXT NOT NULL DEFAULT 'debit' CHECK (payment_method IN ('debit','credit')), ADD COLUMN necessity TEXT NOT NULL DEFAULT 'review' CHECK (necessity IN ('review','necessary','unnecessary')), ADD COLUMN is_transfer BOOLEAN NOT NULL DEFAULT false, ADD COLUMN external_id TEXT;
CREATE UNIQUE INDEX transactions_external_owner_idx ON public.transactions(user_id, external_id) WHERE external_id IS NOT NULL;
CREATE TABLE public.savings_goals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL DEFAULT auth.uid(), name TEXT NOT NULL CHECK (length(trim(name)) > 0), target NUMERIC(12,2) NOT NULL CHECK (target > 0), account TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.savings_goals TO authenticated;
GRANT ALL ON public.savings_goals TO service_role;
ALTER TABLE public.savings_goals ENABLE ROW LEVEL SECURITY;
CREATE POLICY goals_owner ON public.savings_goals FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE TABLE public.goal_contributions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL DEFAULT auth.uid(), goal_id UUID NOT NULL, amount NUMERIC(12,2) NOT NULL CHECK (amount > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY(goal_id,user_id) REFERENCES public.savings_goals(id,user_id) ON DELETE CASCADE);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.goal_contributions TO authenticated;
GRANT ALL ON public.goal_contributions TO service_role;
ALTER TABLE public.goal_contributions ENABLE ROW LEVEL SECURITY;
CREATE POLICY contributions_owner ON public.goal_contributions FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE TABLE public.bank_connections (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, item_id TEXT NOT NULL UNIQUE, bank_name TEXT NOT NULL, synced_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
GRANT SELECT, DELETE ON public.bank_connections TO authenticated;
GRANT ALL ON public.bank_connections TO service_role;
ALTER TABLE public.bank_connections ENABLE ROW LEVEL SECURITY;
CREATE POLICY connections_read ON public.bank_connections FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY connections_delete ON public.bank_connections FOR DELETE TO authenticated USING (auth.uid() = user_id);
COMMENT ON TABLE public.bank_connections IS 'Only verified Pluggy clientUserId ownership may be saved by authenticated server operations.';